import math
def control(obs):
    m=obs['local_map']
    def at(points,u):
        p=sorted(points)
        for a,b in zip(p,p[1:]):
            if a[0]<=u<=b[0] and b[0]-a[0]>0.0001:
                f=(u-a[0])/(b[0]-a[0])
                return a[1]+f*(b[1]-a[1])
        return None
    left=m.get('left_rail',[])
    right=m.get('right_rail',[])
    centers=[]
    for u in (0.3,0.8,1.3,1.8):
        l=at(left,u); r=at(right,u)
        if l is not None and r is not None: centers.append((u,(l+r)/2))
    if centers:
        u,c=centers[-1]
        desired=max(-22,min(22,math.degrees(math.atan2(c,u))*1.1))
    else:
        desired=0
    hitch=obs['hitch_deg']
    steer=max(-45,min(45,2.2*(hitch-desired)))
    return steer,-0.38

