def control(o):
    m=o['local_map']
    def interp(points, x):
        p=sorted(points)
        for a,b in zip(p,p[1:]):
            if a[0]<=x<=b[0] and b[0]-a[0]>0.01:
                return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
        return None
    centers=[]
    for x in (3,6,9,12,15):
        l=interp(m['left_rail'],x); r=interp(m['right_rail'],x)
        if l is not None and r is not None:
            centers.append((x,(l+r)/2))
    if centers:
        x,y=centers[-1]
        desired=max(-18,min(18,math.degrees(math.atan2(y,x))*1.4))
    else: desired=0
    h=o['hitch_deg']
    steer=max(-35,min(35,2.0*(h+desired)))
    return (steer,-0.9,180)

